local OverseaManageMerchantInfoDialog = Class("OverseaManageMerchantInfoDialog")
local SellType = {
    Sell = 1,
    Recycle = 2,
}
function OverseaManageMerchantInfoDialog:__init()
end

function OverseaManageMerchantInfoDialog:__delete()
    self.controller = nil
end

function OverseaManageMerchantInfoDialog:Awake()
    SetButtonAction(self.BtnBuy,Bind(self,self.OnBtnBuyClick))
    SetButtonAction(self.BtnIllustrate,Bind(self,self.OnBtnIllustrateClick))

    ---@type CommonGoodsListLight
    local goodEnv = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    if not isNull(goodEnv) then
        self.goodEnv = goodEnv
    end
end

function OverseaManageMerchantInfoDialog:RefreshShow()
    local data = self:GetData()
    self.data = data
    local isBuy = self:GetIsBuy()
    local state = isBuy and 2 or 1
    local numVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 53)
    local goodsId = self:GetGoodsId()
    local des = self:GetDes(isBuy,numVo.num)
    CfUtils.FillText(self.TextName,des)
    CfUtils.SetUISwitchText(self.TextDecorate1,state)
    CfUtils.SetUISwitchImage(self.ImgText,state)
    CfUtils.SetUISwitchImage(self.ImgBg2,state)
    CfUtils.SetUISwitchImage(self.ImgLine1,state)
    CfUtils.SetUISwitchImage(self.ImgLine2,state)
    CfUtils.SetUISwitchImage(self.ImgSymbol,state)
    CfUtils.SetUISwitchText(self.TextDesc,state)

    local isOther = self:IsOther()
    CfUtils.SetActive(self.TxtNumber.gameObject,isOther)
    if isOther then
        CfUtils.FillText(self.TxtNumber,self.data.merchant.goodsStock)
    end

    CfUtils.SetActive(self.TxtPurchasable.gameObject, isBuy)
    CfUtils.SetActive(self.AverageCostGroup.gameObject,not isBuy)
    CfUtils.SetActive(self.TxtHold.gameObject,not isBuy)
    local maxNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 55).num)


    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if not isNull(goodsVo) then
        CfUtils.FillImage(self.ImgGood,goodsVo.photoPath)
    end


    local canBuyNum = maxNum - self:GetHaveGoodsNum() + checkNumber(data.goodsInitNum)
    if isBuy then
        self:RefreshBtnCost(goodsVo,self.data.merchant.goodsPrice,1)
        CfUtils.FillText(self.TxtPurchasable,localize("本周还可以购买：_num_",{ _num_ = canBuyNum }))
    else
        CfUtils.FillText(self.TxtHold,localize("持有: _num_",{ _num_ = self:GetHaveGoodsNum() }))
        CfUtils.FillText(self.TxtNum,self.data.goodsAverageCost)
        self:RefreshBtnCost(goodsVo,self.data.merchant.goodsPrice,1)
    end

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 52)

    self.goodEnv:FreshBaseUI({[1] = {goodsId = checkNumber(vo.num) ,num = checkNumber(numVo.num)} })

    local scr = CfUtils.GetLuaScr(self.QuantitySlider, "Game.UI.Common.CommonSliderNode")
    if isNull(scr) then return end

    local buyNum = (canBuyNum > 0) and canBuyNum or 1
    --- 要在库存和可购买数量之间取最小值  防止超出购买不了 出售也是一样
    buyNum = isOther and math.min(buyNum,self.data.merchant.goodsStock) or math.min(buyNum,99999)
    local sellNum = (self:GetHaveGoodsNum() > 0) and self:GetHaveGoodsNum() or 1
    sellNum = isOther and math.min(sellNum,self.data.merchant.goodsStock) or math.min(sellNum,99999)
    local maxNum = isBuy and buyNum or sellNum
    scr:RefreshNode(
            0,
            1,
            maxNum,
            Bind(self, self.SliderOnValueChangedHandler)
    )
    CfUtils.SetActive(self.controller.gameObject,true)
end

function OverseaManageMerchantInfoDialog:RefreshBtnCost(goodsVo,goodsNum,costNum)
    if not isNull(goodsVo) then
        CfUtils.FillImage(self.ImgBuyGood,goodsVo.photoPath)
    end
    local isEnough = GoodsUtils.GetThingNo(self.goodsId) >= goodsNum * costNum
    local isBuy = self:GetIsBuy()
    if isBuy then
        local color = isEnough and "<color=#FFFFFF>%s</color>" or "<color=#e71f55>%s</color>"
        CfUtils.FillText(self.BuyNum,string.format(color,goodsNum * costNum))
    else
        CfUtils.FillText(self.BuyNum,goodsNum * costNum)
    end
end

function OverseaManageMerchantInfoDialog:SliderOnValueChangedHandler(value)
    self.curNum = value
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
    self:RefreshBtnCost(goodsVo,self.data.merchant.goodsPrice,self.curNum)

    local vo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 52)
    self.goodEnv:FreshBaseUI({[1] = {goodsId = checkNumber(vo.num) ,num = self.curNum} })
end

function OverseaManageMerchantInfoDialog:GetDes(isBuy,num)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
    if isBuy then
        return localize("_num_颗大头菜_price__name_，你要买几颗？",{_num_ = num ,_price_ = self.data.merchant.goodsPrice,_name_ = goodsVo.name})
    else
        return localize("今天大头菜回收价_num__name__num2_颗，卖吗",{_num_ = self.data.merchant.goodsPrice ,_name_ = goodsVo.name,_num2_ = num})
    end
end

function OverseaManageMerchantInfoDialog:GetIsBuy()
    return checkNumber(self.data.merchant.type) == SellType.Sell
end

function OverseaManageMerchantInfoDialog:GetData()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetMerchantData()
    return data
end

function OverseaManageMerchantInfoDialog:OnBtnBuyClick()
    local isBuy = self:GetIsBuy()
    ---购买大头菜  和出售大头菜
    if isBuy then
        self:Buy()
    else
        self:SellOut()
    end
end

function OverseaManageMerchantInfoDialog:OnBtnIllustrateClick()
    CfUtils.ShowModuleToast(Constants.SystemToggleIds.Id266)
end

function OverseaManageMerchantInfoDialog:SellOut()
    local haveNum = checkNumber(self:GetHaveGoodsNum())
    if haveNum <= 0 then
        GameUtils.Toast(localize("拥有数量不足"))
        return
    end

    local stock = self:IsOther() and self.data.merchant.goodsStock or 9999
    if stock <= 0 then
        GameUtils.Toast(localize("库存不足"))
        return
    end

    local sellNum = self.curNum ~= nil and self.curNum or 1
    local friendId = self:GetFriendId()
    GameUtils.Request(Interfaces.OverseaCafeDarkMerchantRecovery,{friendId = friendId,goodsNum = sellNum},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            GoodsUtils.ConsumeGoods(responseData.consume, true)

            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
            maidCoffeeHomeDojo:UpdateMerchantRecoveryInfo(-responseData.goodsNum,responseData.goodsStock,true)

            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards, true)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end



            self:RefreshShow()
        end
    end)

end

function OverseaManageMerchantInfoDialog:Buy()
    local stock = self:IsOther() and self.data.merchant.goodsStock or 9999
    if stock <= 0 then
        GameUtils.Toast(localize("库存不足"))
        return
    end
    local maxNum = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 55).num)
    local haveNum = checkNumber(self:GetHaveGoodsNum() - checkNumber(self.data.goodsInitNum))
    if haveNum >= maxNum then
        GameUtils.Toast(localize("本周可购买数量已达上限"))
        return
    end

    local buyNum = self.curNum ~= nil and self.curNum or 1
    local buyCost = self.data.merchant.goodsPrice * buyNum
     local haveNum = GoodsUtils.GetThingNo(self.goodsId)
    if haveNum < buyCost then
        GameUtils.Toast(localize("道具不足"))
        return
    end

    local friendId = self:GetFriendId()

    GameUtils.Request(Interfaces.OverseaCafeDarkMerchantSale,{friendId = friendId,goodsNum = buyNum},function(request,response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
            local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
            maidCoffeeHomeDojo:UpdateMerchantRecoveryInfo(responseData.goodsNum,responseData.goodsStock)
            GoodsUtils.ConsumeGoods(responseData.consume, true)
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards, true)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })
            end
            self:RefreshShow()
        end
    end)
end

function OverseaManageMerchantInfoDialog:GetFriendId()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    ---如果是在别人家里  不刷新
    local isOther = maidCoffeeHomeDojo:IsOther()
    local friendId = isOther and maidCoffeeHomeDojo:GetFriendId() or 0
    return friendId
end

function OverseaManageMerchantInfoDialog:IsOther()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    ---如果是在别人家里  不刷新
    return maidCoffeeHomeDojo:IsOther()
end

function OverseaManageMerchantInfoDialog:GetHaveGoodsNum()
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidCoffeeHomeDojo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local data = maidCoffeeHomeDojo:GetSelfMerchantData()
    return checkNumber(data.goodsNum)
end

function OverseaManageMerchantInfoDialog:GetGoodsId()
    local goodIdVo = CfUtils.GetCfVo(AutoIds.IdSetting3033, "MaidCoffeeManagerSettingVo", 54)
    self.goodsId = checkNumber(goodIdVo.num)
    return self.goodsId
end

return OverseaManageMerchantInfoDialog